    final server = _server!;
    final url = 'http://127.0.0.1:${server.port}/';

    _timeoutTimer = Timer(timeout, () {
      if (_codeCompleter case final c? when !c.isCompleted) {
        c.complete(null);
      }
      unawaited(close());
    });

    server.listen(_handleRequest, onDone: _onDone);

    return url;
  }

