+          isLinux: true,
+        ),
+        isTrue,
+      );
+    });
+
+    test('the display check is Linux-only (macOS/Windows need none)', () {
+      expect(
+        isHeadlessOrRemoteSession(
+          environment: const {},
+          stdoutHasTerminal: true,
