+                '&provider=$provider',
+            'state': 'it-state-1',
+            'expires_in': 900,
+          }),
+          200,
+        );
+      }
+      if (host == 'auth.aiin.by' && path == '/api/oauth-proxy/exchange') {
+        return http.Response(
+          jsonEncode({
+            'access_token': [REDACTED:Sensitive Value] 'user@aiin.by'),
+            'refresh_token': '[REDACTED:Sensitive Value]',
+            'token_type': 'Bearer',
+            'expires_in': 3600,
