+    final registry = CustomProviderRegistry([]);
+    final cli = cliFor(
+      fake.call,
+      envVarValue: (_) => null,
+      secureKeys: cache,
+      customProviders: registry,
+      codeMieGuidedSetupFn: (apiBase, cookie, pickOption, askLine) async =>
+          'codemie-model-1',
