+    test('the flag wins over a truthy env var (both set: flag wins)', () {
+      expect(
+        shouldLaunchBrowser(
+          noBrowserFlag: true,
+          environment: const {'FA_NO_BROWSER': '1', 'DISPLAY': ':0'},
+          stdoutHasTerminal: true,
