+    test('SSH markers apply on every platform', () {
+      expect(
+        isHeadlessOrRemoteSession(
+          environment: const {'SSH_CONNECTION': '10.0.0.1 5000 10.0.0.2 22'},
+          stdoutHasTerminal: true,
+          isLinux: false,
+        ),
