+
+  group('shouldLaunchBrowser (precedence: flag > env > auto-detect)', () {
+    test('launches for an interactive local session', () {
+      expect(
+        shouldLaunchBrowser(
+          environment: const {'DISPLAY': ':0'},
+          stdoutHasTerminal: true,
