+    test('non-truthy FA_NO_BROWSER values do not skip the launch', () {
+      for (final value in const ['0', 'false', '', 'no', 'off']) {
+        expect(
+          shouldLaunchBrowser(
+            environment: {'FA_NO_BROWSER': value, 'DISPLAY': ':0'},
+            stdoutHasTerminal: true,
+            isLinux: true,
+          ),
