+          stdoutHasTerminal: true,
+          isLinux: true,
+        ),
+        isFalse,
+      );
+    });
+
+    test('env beats auto-detect (env set on an interactive session: skip)',
+        () {
+      expect(
+        shouldLaunchBrowser(
+          environment: const {'FA_NO_BROWSER': 'yes', 'DISPLAY': ':0'},
+          stdoutHasTerminal: true,
+          isLinux: true,
+        ),
+        isFalse,
+      );
