+        expect(
+          shouldLaunchBrowser(
+            environment: env,
+            stdoutHasTerminal: terminal,
+            isLinux: true,
+          ),
+          isFalse,
+          reason: '$label must skip the launch',
+        );
+      }
+    });
+  });
