+          stdoutHasTerminal: true,
+          isLinux: true,
+        ),
+        isTrue,
+      );
+    });
+
+    test('SSH_CONNECTION alone marks the session remote', () {
+      expect(
+        isHeadlessOrRemoteSession(
+          environment: const {
+            'DISPLAY': ':0',
