+    test('launches for an interactive local session', () {
+      expect(
+        shouldLaunchBrowser(
+          environment: const {'DISPLAY': ':0'},
+          stdoutHasTerminal: true,
+          isLinux: true,
+        ),
+        isTrue,
+      );
+    });
+
+    test('the --no-browser flag alone skips the launch', () {
+      expect(
+        shouldLaunchBrowser(
+          noBrowserFlag: true,
+          environment: const {'DISPLAY': ':0'},
+          stdoutHasTerminal: true,
+          isLinux: true,
+        ),
+        isFalse,
+      );
+    });
+
+    test('a truthy FA_NO_BROWSER alone skips the launch', () {
