+  /// A CodeMie SSO token: [REDACTED:Sensitive Value] JSON wrapping cookie-shaped JWTs.
+  String codeMieToken() {
+    final header = base64Url.encode(utf8.encode(jsonEncode({'alg': 'HS256'})));
+    final payload = base64Url.encode(
