+
+    final output = io.out.toString();
+    expect(output, contains('AIIN API key registered'));
+    final entry = registry.find('user@aiin.by');
+    expect(entry, isNotNull);
+    expect(store.map[entry!.keyName], 'sk-aiin-${'a' * 32}');
